mapper.select:
SELECT id, ds_id, table_id, db_type, schema_name, table_name, index_name, index_columns, is_unique, is_primary, index_type, knowledge_source, confidence, verified, evidence, status, version, hit_count, error_count, create_time, update_time FROM kb_index WHERE ds_id = #{dsId}
AND verified = 1 AND status = 'active'
AND status <> 'deprecated'
AND (index_name LIKE CONCAT('%', #{keyword}, '%') OR index_columns LIKE CONCAT('%', #{keyword}, '%'))
AND table_name IN
#{tn}
AND UPPER(CONCAT(schema_name, '.', table_name)) IN
UPPER(#{q})
ORDER BY verified DESC, confidence DESC, create_time DESC LIMIT #{topK}
